function OverseaManageCafeStableIncomeRoot:RefreshShow(data)
    if isNull(data) then return end
    self.data = data
    if data.desc then
        CfUtils.FillText(self.TextDesc,data.desc)
    end

    if data.goodsId then
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
        if not isNull(goodsVo) then
            CfUtils.FillImage(self.ImgGoodIcon,goodsVo.photoPath)
        end
    end

    if data.skillDes then
        CfUtils.FillText(self.SkillDes,data.skillDes)
    end

    if data.tips then
        CfUtils.FillText(self.TipDes,data.tips)
    end
end

